const $v=id=>document.getElementById(id);
const phases={idle:'尚未开始',connecting:'正在连接',listening:'等你说话',thinking:'云端正在回复',speaking:'板上正在播报',interrupting:'正在停止播报',error:'连接中断'};
let formLoaded=false,busy=false,lastVoice={};
function voiceTime(seconds){const n=Math.floor(seconds||0);return `${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`;}
async function voiceAPI(path,body){const r=await fetch(path,{method:body===undefined?'GET':'POST',headers:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)});const data=await r.json();if(!r.ok)throw new Error(data.error||'请求失败');return data;}
function voiceNotice(text,error=false){$v('voiceNotice').textContent=text;$v('voiceNotice').classList.toggle('error',error);$v('voiceNotice').hidden=!text;}
function fillVoiceConfig(c){for(const [id,key]of Object.entries({voiceInteractionMode:'interaction_mode',voiceInterruptionMS:'interruption_min_speech_ms',voiceHost:'api_host',voiceASRModel:'asr_model',voiceTTSModel:'tts_model',voiceName:'voice',voiceProxy:'proxy',voiceVolume:'volume',voiceLimit:'max_session_seconds',voiceInstructions:'instructions'}))$v(id).value=c[key]??'';$v('voiceKey').placeholder=c.key_present?'已保存；留空可保留原 Key':'粘贴云语音 API Key（sk-…）';$v('voiceVolumeText').textContent=c.volume;formLoaded=true;}
function paintVoice(data){lastVoice=data;const s=data.session,c=data.config,active=s.active;const automatic=active?s.mode==='aec_asr_confirmed_interrupt':c.interaction_mode==='automatic_interrupt';$v('voiceModeHint').textContent=automatic?'声音来自开发板麦克风，回答从板上喇叭播放。自动打断模式下，可说“等等”或直接提出新问题。短句完整播完后才进入对话历史。连接自检只播放短提示音，不调用付费 API。':'声音来自开发板麦克风，回答从板上喇叭播放。轮流说话模式在播报时暂停上传收音，可点“打断播报”。连接自检不调用付费 API。';$v('voicePhase').textContent=s.phase==='idle'&&s.stop_reason?(s.source==='protocol_test'?'连接自检已结束':'通话已结束'):(phases[s.phase]||s.phase);$v('voicePhaseDot').classList.toggle('online',active);$v('voiceClock').textContent=voiceTime(s.elapsed_seconds);$v('voiceSource').textContent=s.source==='protocol_test'?'协议自检 · 非 AI 对话':'ASR → DeepSeek → TTS';$v('voiceSource').classList.toggle('simulated',s.source==='protocol_test');$v('voiceConfigured').textContent=data.recording_active?'原始录音进行中，停止录音后可开始语音':c.configured?(c.interaction_mode==='automatic_interrupt'&&!data.automatic_interrupt_ready?'板上回声消除尚未就绪，可选择轮流说话':'云语音 Key 与 API Host 已配置'):(c.error||'待填写云语音 Key 与 API Host');$v('voiceStart').disabled=busy||active||data.recording_active||!data.board_ready||!c.configured||(c.interaction_mode==='automatic_interrupt'&&!data.automatic_interrupt_ready);$v('voiceTest').disabled=busy||active||data.recording_active||!data.board_ready;$v('voiceStop').disabled=busy||!active;$v('voiceInterrupt').disabled=busy||!active||!['thinking','speaking'].includes(s.phase);$v('voiceSave').disabled=busy||active;if(!formLoaded)fillVoiceConfig(c);if(active&&!s.error)voiceNotice('');else if(s.error)voiceNotice(s.error,true);else if(!active&&s.stop_reason==='self_test_complete')voiceNotice('连接自检通过：实板音频收发已验证。请在现场确认是否听到短提示音。');else if(!active&&s.stop_reason==='session_time_limit')voiceNotice('已达到本次通话时长上限，连接已关闭。');const m=s.metrics||{};$v('voiceInputBytes').textContent=`${((m.uplink_bytes||0)/1024).toFixed(1)} KiB`;$v('voiceOutputBytes').textContent=`${((m.downlink_bytes||0)/1024).toFixed(1)} KiB`;$v('voiceMicDrops').textContent=m.mic_drops||0;$v('voiceSpeakerFrames').textContent=m.speaker_frames||0;$v('voiceAutoInterrupts').textContent=m.auto_interruptions||0;$v('voicePlayedSegments').textContent=m.played_segments||0;const timing=m.current_turn_timing||{};const duration=value=>typeof value==='number'?(value/1000).toFixed(2)+' 秒':'—';$v('voiceFirstAudio').textContent=duration(timing.first_tts_audio_received_ms);$v('voiceFirstSend').textContent=duration(timing.first_speaker_send_ms);const root=$v('voiceTranscript');const identity=JSON.stringify(s.messages);if(root.dataset.content!==identity){root.replaceChildren();for(const msg of s.messages){const row=document.createElement('article');row.className='voice-turn';const label=document.createElement('strong'),content=document.createElement('p');label.textContent=s.source==='protocol_test'?'协议自检':(({user:'你',assistant:'DeepSeek',system:'提示'}[msg.role]||'提示')+(msg.interrupted?' · 已打断':msg.delivered?' · 已播完':msg.partial?' · 生成／播报中':''));content.textContent=msg.text+(msg.partial?'…':'');row.append(label,content);root.append(row);}root.dataset.content=identity;}}
async function refreshVoice(){try{paintVoice(await voiceAPI('/api/voice/status'));}catch{ $v('voiceConfigured').textContent='本机语音服务未连接';}}
async function voiceAction(path){busy=true;voiceNotice('');await refreshVoice();try{const mute=document.getElementById('mute');if(mute){mute.checked=true;mute.dispatchEvent(new Event('change'));}await voiceAPI(path,{});}catch(error){voiceNotice(error.message,true);}finally{busy=false;await refreshVoice();}}
$v('voiceStart').onclick=()=>voiceAction('/api/voice/start');$v('voiceStop').onclick=()=>voiceAction('/api/voice/stop');$v('voiceInterrupt').onclick=()=>voiceAction('/api/voice/interrupt');$v('voiceTest').onclick=()=>voiceAction('/api/voice/self-test');
$v('voiceVolume').oninput=()=>$v('voiceVolumeText').textContent=$v('voiceVolume').value;
$v('voiceConfigForm').onsubmit=async event=>{event.preventDefault();busy=true;try{const result=await voiceAPI('/api/voice/config',{interaction_mode:$v('voiceInteractionMode').value,interruption_min_speech_ms:Number($v('voiceInterruptionMS').value),api_host:$v('voiceHost').value.trim(),asr_model:$v('voiceASRModel').value.trim(),tts_model:$v('voiceTTSModel').value.trim(),voice:$v('voiceName').value.trim(),proxy:$v('voiceProxy').value.trim(),api_key:$v('voiceKey').value.trim(),volume:Number($v('voiceVolume').value),max_session_seconds:Number($v('voiceLimit').value),instructions:$v('voiceInstructions').value});$v('voiceKey').value='';fillVoiceConfig(result);voiceNotice('语音配置已保存。保存不会自动开始通话。');}catch(error){voiceNotice(error.message,true);}finally{busy=false;await refreshVoice();}};
refreshVoice();setInterval(refreshVoice,1000);
